templates.react:
export function Page({
  layout = "{{layout}}",
  title = "{{title}}",
  showLabels = {{showLabels}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, overflow: "hidden", fontFamily: "system-ui, sans-serif", fontSize: 11, color: "#241430aa" }}>
      <div style={{ padding: "4px 10px", background: "#24143011", fontSize: 10 }}>{title}</div>
      <div style={{ padding: 10, textAlign: "center", color: "#241430", fontWeight: 600, background: accent }}>{showLabels && "header"}</div>
      <div style={{ display: "flex", minHeight: 70 }}>
        {layout === "with-sidebar" && <div style={{ width: 60, background: "#24143011", padding: 10, boxSizing: "border-box" }}>{showLabels && "nav"}</div>}
        <div style={{ flex: 1, padding: 10, background: "#fff" }}>{showLabels && "main content"}</div>
      </div>
      <div style={{ padding: "8px 10px", background: "#24143011", textAlign: "center" }}>{showLabels && "footer"}</div>
    </div>
  );
}
